/**
 * A graph with the terms Turtle export has to get right (quotes, line breaks, languages, datatypes, blank nodes, IRIs
 * that cannot be prefixed); GraphExplorerQueryTest parses its export, graph-export.ttl, with Rio.
 */
export function exportFixtureGraph() {
  const uri = (value) => ({ type: "uri", value });
  const literal = (value, extra = {}) => ({ type: "literal", value, ...extra });
  const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });
  const ex = "http://example.org/";
  const schema = "http://schema.org/";
  const label = "http://www.w3.org/2000/01/rdf-schema#label";
  const reifies = row(uri(`${ex}claim`), "http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies", {
    type: "triple",
    value: { subject: uri(`${ex}alice`), predicate: uri(`${schema}knows`), object: uri(`${ex}bob`) },
  });
  return mergeStatementLinks(mergeTriples(
    { nodes: [], edges: [], revision: 0 },
    bindingsToTriples([
      row(uri(`${ex}alice`), "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", uri(`${schema}Person`)),
      row(uri(`${ex}alice`), label, literal('Alice "Al" Smith', { "xml:lang": "en" })),
      row(uri(`${ex}alice`), label, literal("line\nbreak")),
      row(uri(`${ex}alice`), `${schema}age`, literal("39", { datatype: "http://www.w3.org/2001/XMLSchema#integer" })),
      row(uri(`${ex}alice`), `${schema}knows`, uri(`${ex}bob`)),
      row(uri(`${ex}alice`), `${schema}knows`, { type: "bnode", value: "b1" }),
      row(uri(`${ex}alice`), `${ex}odd#name.`, literal("x")),
      row(uri(`${ex}bob`), `${schema}worksFor`, uri(`${ex}acme%20corp`)),
      row({ type: "bnode", value: "b1" }, label, literal("Somebody")),
    ]),
  ), statementLinksOf([reifies]));
}

export const fixtureDirectory = fileURLToPath(new URL("../src/test/resources/graph-explorer-queries/", import.meta.url));

export function expectedCountsText(fixtures = queryFixtures()) {
  return "# Generated by `npm run fixtures:queries` in tools/workbench; do not edit by hand.\n"
    + fixtures.map(([name, , count]) => `${name}=${count}`).join("\n") + "\n";
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  mkdirSync(fixtureDirectory, { recursive: true });
  const fixtures = queryFixtures();
  for (const [name, query] of fixtures) {
    writeFileSync(`${fixtureDirectory}${name}.rq`, query.endsWith("\n") ? query : query + "\n");
  }
  writeFileSync(`${fixtureDirectory}expected-counts.properties`, expectedCountsText(fixtures));
  writeFileSync(`${fixtureDirectory}graph-export.ttl`, graphTurtle(exportFixtureGraph()));
  console.log(`wrote ${fixtures.length} query fixtures to ${fixtureDirectory}`);
}
